((root) => {
  'use strict';
  const entry = (ar,en,whyAr,whyEn,checkAr,checkEn,riskAr,riskEn) =>
    ({name:[ar,en], why:[whyAr,whyEn], check:[checkAr,checkEn], risk:[riskAr,riskEn]});
  const cases = [
    entry('تسرّع قلب غير منتظم؛ يُشتبه برجفان أذيني','Irregular tachycardia; possible atrial fibrillation','النبض سريع وغير منتظم في ملف الحالة.','The case has a fast, irregular pulse.','تخطيط 12 اشتقاقًا، ضغط الدم، ومراجعة احتمال الخوارج أو التشوش.','12-lead ECG, blood pressure, and review for ectopy or artifact.','قد يحدث هبوط ضغط أو إغماء إذا استمر التسارع مع ضعف التروية.','Persistent tachycardia with poor perfusion may cause hypotension or syncope.'),
    entry('بطء قلب؛ يُشتبه ببطء جيبي أو اضطراب توصيل','Bradycardia; possible sinus bradycardia or conduction disease','معدل النبض منخفض. وجود أعراض هو ما يغيّر درجة القلق.','Pulse is low. Symptoms change the level of concern.','تأكيد النبض والضغط، تخطيط 12 اشتقاقًا، ومراجعة الأدوية.','Confirm pulse and blood pressure, obtain a 12-lead ECG, and review medications.','إذا ترافق مع ضعف التروية، قد يظهر دوار أو إغماء.','Dizziness or syncope may develop if perfusion is impaired.'),
    entry('إجهاد حراري؛ احتمال إنهاك حراري','Heat stress; possible heat exhaustion','ارتفاع النبض وحرارة الجلد يدعمان الاشتباه عند وجود تعرض للحرارة.','Higher pulse and skin temperature support concern when heat exposure is present.','اسألي عن التعرض للحرارة، وافحصي الوعي وحرارة الجسم المركزية.','Verify heat exposure and assess mental status and core temperature.','اضطراب الوعي بعد التعرض للحرارة يرفع الاشتباه بضربة حرارية.','Altered mental status after heat exposure raises concern for heat stroke.'),
    entry('ضيق نفس حاد؛ يُبحث عن تشنج قصبي أو سبب قلبي رئوي','Acute dyspnea; assess for bronchospasm or cardiopulmonary causes','ضيق النفس مع تسارع النبض وحركة صدر متغيرة.','Dyspnea with a fast pulse and changing chest movement.','قياس تشبع الأكسجين ومعدل التنفس وفحص الصدر. تشمل البدائل الانصمام الرئوي والاسترواح بحسب القصة والفحص.','Measure oxygen saturation and respiratory rate and examine the chest. Consider pulmonary embolism or pneumothorax as indicated.','قد يتفاقم نقص الأكسجة أو جهد التنفس إذا تطور السبب.','Hypoxemia or respiratory distress may worsen if the cause progresses.'),
    entry('دوار مع اضطراب اتزان؛ احتمال سبب دهليزي أو عصبي','Dizziness with imbalance; vestibular or neurologic cause possible','تغير الوضعية يدعم وجود حركة أو عدم اتزان عند مطابقته للأعراض.','Position changes support movement or imbalance when consistent with symptoms.','تحديد بدء الأعراض، فحص عصبي واتزان، وقياس السكر. عجز عصبي جديد يرفع الاشتباه بالسكتة.','Establish onset, perform neurologic and balance assessment, and check glucose. New focal deficits raise concern for stroke.','خطر السقوط قائم. استمرار الأعراض أو عجز عصبي يستدعي تقييمًا عاجلًا.','Falls are possible. Persistent symptoms or focal deficits require urgent assessment.'),
    entry('اشتباه نقص تروية جهازية؛ احتمال صدمة دورانية','Suspected systemic hypoperfusion; possible circulatory shock','نبض سريع مع تغير حرارة الجلد يثير الاشتباه إذا صاحبه ضعف تروية بالفحص.','Fast pulse and skin-temperature changes raise concern when accompanied by poor perfusion on examination.','قياس الضغط والوعي، فحص التروية والنزف، والبحث عن عدوى أو سبب قلبي.','Measure pressure and mental status, assess perfusion and bleeding, and look for infection or a cardiac cause.','قد تتدهور التروية والوعي ووظائف الأعضاء إذا ثبتت الصدمة واستمرت.','Persistent shock may impair perfusion, consciousness, and organ function.'),
    entry('ألم صدري حاد؛ تُستبعد متلازمة الشريان التاجي الحادة','Acute chest pain; rule out acute coronary syndrome','الألم الصدري هو القرينة الأساسية. النبض المتغير لا يحدد السبب.','Chest pain is the principal finding. A variable pulse does not establish the cause.','تقييم عاجل، تخطيط 12 اشتقاقًا وتروبونين بحسب البروتوكول، وفحص البدائل الخطرة.','Urgent evaluation, 12-lead ECG and troponin per protocol, and assessment for dangerous alternatives.','إذا كان السبب إقفاريًا، قد يتطور احتشاء أو اضطراب نظم.','An ischemic cause may progress to infarction or arrhythmia.'),
    entry('قشعريرة مع رعاش؛ احتمال عدوى أو تعرض للبرد','Rigors with tremor; infection or cold exposure possible','الرعشة قد تغيّر إشارة الحركة وتشوّش تسجيل القلب.','Tremor can alter motion data and introduce ECG artifact.','قياس حرارة الجسم، وفحص وجود أعراض عدوى، والضغط والتنفس والوعي.','Measure body temperature and assess for infection, blood pressure, breathing, and mental status.','مع عدوى وخلل في الوظائف الحيوية يرتفع الاشتباه بالإنتان.','Infection with physiologic deterioration raises concern for sepsis.'),
    entry('إغماء محتمل؛ تُبحث الأسباب الانعكاسية والقلبية','Possible syncope; assess reflex and cardiac causes','تغير الوضعية ثم الاستقرار يستدعي التحقق من حدوث فقدان وعي عابر.','Position change followed by recovery warrants checking whether transient loss of consciousness occurred.','قصة الشاهد، توقيت الحدث، تخطيط القلب، الضغط والسكر.','Witness history, timing, ECG, blood pressure, and glucose.','قد يتكرر السقوط أو الإصابة. حدوثه أثناء الجهد يرفع القلق من سبب قلبي.','Recurrence can cause injury. Exertional syncope raises concern for a cardiac cause.'),
    entry('خفقان مع قلق؛ احتمال تسرع جيبي مرتبط بالضغط النفسي','Palpitations with anxiety; possible stress-related sinus tachycardia','تغير النبض بالتزامن مع القلق يدعم الاحتمال بعد استبعاد الأسباب الأخرى.','Pulse varying with anxiety supports the possibility after other causes are considered.','تخطيط القلب، الضغط، مراجعة المنبهات، والتحقق من الألم وضيق النفس والإغماء.','ECG, blood pressure, stimulant history, and assessment for pain, dyspnea, or syncope.','الاستمرار في الراحة أو ظهور علامات إنذار يستدعي إعادة التقييم.','Persistence at rest or new red flags warrants reassessment.'),
    entry('استجابة فسيولوجية محتملة بعد الجهد','Possible physiologic post-exertional response','هبوط النبض نحو خط الأساس بعد الجهد مع غياب الأعراض يدعم التعافي.','Pulse returning toward baseline without symptoms supports recovery.','تأكيد زمن الجهد وقياس النبض بعد الراحة والسؤال عن أعراض مستمرة.','Confirm exertion timing, recheck pulse after rest, and ask about ongoing symptoms.','إذا استمر التسارع أو ظهر ألم أو إغماء، يلزم البحث عن سبب آخر.','Persistent tachycardia, pain, or syncope warrants investigation for another cause.'),
    entry('برودة جلد؛ احتمال تعرض للبرد أو ضعف تروية محيطية','Cool skin; possible cold exposure or reduced peripheral perfusion','انخفاض حرارة الجلد قراءة موضعية وتتأثر بالبيئة والتلامس.','Low skin temperature is local and influenced by ambient conditions and contact.','قياس حرارة الجسم المركزية، الضغط، فحص التروية والوعي.','Measure core temperature and pressure and assess perfusion and mental status.','إذا ثبت انخفاض حرارة الجسم، قد تتأثر الوظائف العصبية ونظم القلب.','Confirmed hypothermia may affect neurologic function and cardiac rhythm.'),
    entry('اشتباه سكتة دماغية حادة','Suspected acute stroke','سُجل ضعف مفاجئ في جهة أو اضطراب كلام.','Sudden focal weakness or speech change was recorded.','وقت آخر حالة طبيعية، قياس السكر، تقييم عصبي وتصوير عاجل.','Establish last known well, check glucose, and obtain urgent neurologic assessment and imaging.','قد يستمر العجز أو يزداد. سرعة التقييم تؤثر في خيارات العلاج.','Deficits may persist or worsen. Time to assessment affects treatment options.'),
    entry('انخفاض تشبع الأكسجين المسجل','Recorded low oxygen saturation','التشبع المدخل منخفض.','Entered oxygen saturation is low.','أعيدي القياس بإشارة موثوقة وافحصي التنفس والتروية والسياق السريري.','Repeat with a reliable signal and assess breathing, perfusion, and clinical context.','استمرار نقص الأكسجة قد يسبب تغير الوعي أو إجهادًا تنفسيًا.','Persistent hypoxemia can impair consciousness or increase respiratory distress.'),
    entry('اشتباه انخفاض حرارة الجسم','Suspected hypothermia','الحرارة المركزية المدخلة أقل من 35 درجة مئوية.','Entered core temperature is below 35 °C.','أعيدي القياس بطريقة موثوقة وقيّمي الوعي والنظم والتروية.','Confirm with a reliable measurement and assess mental status, rhythm, and perfusion.','قد يتأثر الوعي ونظم القلب إذا استمر الانخفاض.','Ongoing hypothermia may impair consciousness and cardiac rhythm.'),
    entry('اشتباه ضربة حرارية','Suspected heat stroke','تعرض للحرارة مع تغير في الوعي.','Heat exposure and altered mental status were recorded.','يلزم تقييم عاجل للوعي وقياس الحرارة المركزية والبحث عن أسباب أخرى لتغير الوعي.','Urgently assess mental status and core temperature and evaluate other causes of altered consciousness.','قد تحدث اختلاجات أو إصابة أعضاء مع التدهور.','Deterioration can include seizures or organ injury.')
  ];

  function assess({signs=[], age, pulse, sbp, oxygen, coreTemp}) {
    const has = key => signs.includes(key);
    const adult = Number.isFinite(age) && age >= 18;
    const urgent = has('chest') || has('dyspnea') || has('syncope') || has('confusion') ||
      has('neuro') || (adult && (sbp <= 90 || oxygen < 92 || coreTemp < 35));
    const rows = [];
    if (has('neuro')) rows.push(12);
    if (has('chest')) rows.push(6);
    if (has('dyspnea')) rows.push(3);
    if (has('syncope')) rows.push(8);
    if (has('heat')) rows.push(has('confusion')?15:2);
    if (has('chills')) rows.push(7);
    if (adult && sbp <= 90) rows.push(5);
    if (adult && Number.isFinite(pulse) && pulse < 50) rows.push(1);
    if (adult && oxygen < 92) rows.push(13);
    if (adult && coreTemp < 35) rows.push(14);
    else if (has('cold')) rows.push(11);
    return {rows:[...new Set(rows)], urgent, fastPulse:adult && pulse > 100, adult};
  }
  const api = {cases, assess};
  if (typeof module === 'object' && module.exports) module.exports = api;
  else root.MasarClinical = api;
})(globalThis);
